  document.querySelector('#controls ul').innerHTML = tr.controls.map(([key, what]) => `<li><kbd>${esc(key)}</kbd><span>${esc(what)}</span></li>`).join('')
  document.getElementById('hints').innerHTML = tr.controls.slice(0, 4).map(([key, what]) => `<span><kbd>${esc(key)}</kbd>${esc(what)}</span>`).join('')
