// Colours are graphify's (or the script's own when it laid things out itself).
const rgb = hex => [1, 3, 5].map(k => parseInt(hex.slice(k, k + 2), 16)).join(',')
const colourOf = nodes.map(n => n[2])

// ---- Physics ---------------------------------------------------------------
// Every dot has a home: where graphify's page puts it (TX, TY). It is pulled
// there on a spring, connections pull their ends toward the distance their
// homes are apart, and dots too close push each other off. So new code shoots
// out from what it connects to and settles where graphify would show it,
// jostling its neighbours on the way -- the way Gource grows a tree.
const X = new Float32Array(N), Y = new Float32Array(N), VX = new Float32Array(N), VY = new Float32Array(N)
const TX = Float32Array.from(nodes, n => n[0]), TY = Float32Array.from(nodes, n => n[1])
const live = new Uint8Array(N)
// Held firmly to graphify's spot, so its shape survives -- tight clusters with
// empty space between them. Only dots that actually overlap are pushed apart;
// a longer reach spread every cluster to the same even density and filled the
// gaps, which is what turned the picture into a disc.
const HOME = 0.03, SPRING = 0.006, PUSH = 0.001, REACH = 0.012, DAMP = 0.85
const neighbours = Array.from({ length: N }, () => [])
const rest = new Float32Array(edges.length)
edges.forEach(([a, b], i) => {
  neighbours[a].push(b); neighbours[b].push(a)
  rest[i] = Math.hypot(TX[a] - TX[b], TY[a] - TY[b])
})

// When each dot first appears, and where the history starts: the speck of
// light the opening lands in the middle of today's graph, which the first
// files come out of.
const born = nodeIn.map(p => p.indexOf(1))
const FIRST = Math.min(...born.filter(b => b >= 0))
let SEEDX, SEEDY
{
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity
  for (let i = 0; i < N; i++) {
    if (!nodeIn[i][S - 1]) continue
    minX = Math.min(minX, TX[i]); maxX = Math.max(maxX, TX[i]); minY = Math.min(minY, TY[i]); maxY = Math.max(maxY, TY[i])
  }
  SEEDX = (minX + maxX) / 2; SEEDY = (minY + maxY) / 2
}

function spawn(i) {
  // Out of something already there that it connects to, as Gource's files
  // come out of their folder; failing that, the first out of the speck they
  // start from, and later ones near their own home.
  let from = -1
  for (const j of neighbours[i]) if (live[j]) { from = j; break }
  const a = Math.random() * Math.PI * 2, first = Math.floor(pos) <= FIRST
  const ox = from >= 0 ? X[from] : first ? SEEDX : TX[i] + Math.cos(a) * 0.04
  const oy = from >= 0 ? Y[from] : first ? SEEDY : TY[i] + Math.sin(a) * 0.04
  X[i] = ox + Math.cos(a) * 0.002; Y[i] = oy + Math.sin(a) * 0.002
  VX[i] = Math.cos(a) * 0.006; VY[i] = Math.sin(a) * 0.006
}

const grid = new Map()
function step(s) {
  for (let i = 0; i < N; i++) {
    if (!live[i]) continue
    VX[i] += (TX[i] - X[i]) * HOME
    VY[i] += (TY[i] - Y[i]) * HOME
  }
  for (let e = 0; e < edges.length; e++) {
    // The file tree is drawn but doesn't pull: its lines run between clusters,
    // and as springs they drew the clusters together.
    if (!edgeIn[e][s] || edges[e][2]) continue
    const a = edges[e][0], b = edges[e][1]
    if (!live[a] || !live[b]) continue
    const dx = X[b] - X[a], dy = Y[b] - Y[a], d = Math.hypot(dx, dy) || 1e-6
    const f = SPRING * (d - rest[e]) / d * 0.5
    VX[a] += dx * f; VY[a] += dy * f; VX[b] -= dx * f; VY[b] -= dy * f
  }
  // Push apart what is too close, found through a grid so it isn't every pair.
  grid.clear()
  for (let i = 0; i < N; i++) {
    if (!live[i]) continue
    const key = Math.floor(X[i] / REACH) * 100003 + Math.floor(Y[i] / REACH)
    const cell = grid.get(key)
    cell ? cell.push(i) : grid.set(key, [i])
  }
  for (let i = 0; i < N; i++) {
    if (!live[i]) continue
    const gx = Math.floor(X[i] / REACH), gy = Math.floor(Y[i] / REACH)
    for (let ox = -1; ox <= 1; ox++) for (let oy = -1; oy <= 1; oy++) {
      const cell = grid.get((gx + ox) * 100003 + gy + oy)
      if (!cell) continue
      for (const j of cell) {
        if (j <= i) continue
        const d = Math.hypot(X[j] - X[i], Y[j] - Y[i])
        if (d >= REACH) continue
        // Along the line between them, never harder than PUSH. Two dots on the
        // very same spot get a random direction; dividing by their (zero)
        // distance used to fling them clean off the screen.
        const a = d > 1e-6 ? Math.atan2(Y[j] - Y[i], X[j] - X[i]) : Math.random() * Math.PI * 2
        const f = PUSH * (REACH - d) / REACH
        const fx = Math.cos(a) * f, fy = Math.sin(a) * f
        VX[i] -= fx; VY[i] -= fy; VX[j] += fx; VY[j] += fy
      }
    }
  }
  for (let i = 0; i < N; i++) {
    if (!live[i]) continue
    VX[i] *= DAMP; VY[i] *= DAMP
    X[i] += VX[i]; Y[i] += VY[i]
  }
}

// ---- Camera ----------------------------------------------------------------
let W, H, dpr, home, view, follow = true, ended = false
function resize() {
  dpr = window.devicePixelRatio || 1
  W = innerWidth; H = innerHeight
  canvas.width = W * dpr; canvas.height = H * dpr
  home = { x: W / 2, y: H / 2 - 10, s: Math.min(W, H - 110) * 0.47 }
  view = view || { ...home }
}
resize(); addEventListener('resize', resize)
const sx = i => view.x + X[i] * view.s, sy = i => view.y + Y[i] * view.s
const zoom = () => Math.min(2.2, Math.sqrt(view.s / home.s))

// Framing what exists, easing toward it: close in at the start, pulling back
// as the project grows -- and a little further once it's all there.
function frameCamera(snap = false) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity
  for (let i = 0; i < N; i++) {
    if (!live[i]) continue
    if (X[i] < minX) minX = X[i]; if (X[i] > maxX) maxX = X[i]
    if (Y[i] < minY) minY = Y[i]; if (Y[i] > maxY) maxY = Y[i]
  }
  if (minX === Infinity) return
  // Never closer than this much of the graph: less close over the opening,
  // which ends on the speck alone.
  const least = introDone ? 0.25 : 0.7
  const w = Math.max(maxX - minX, least), h = Math.max(maxY - minY, least)
  const s = Math.min((W - 80) / w, (H - 230) / h) * (ended ? 0.86 : 1)
  const target = { s, x: W / 2 - (minX + maxX) / 2 * s, y: (H + 10) / 2 - (minY + maxY) / 2 * s }
  const k = snap ? 1 : 0.035
  view.s += (target.s - view.s) * k
  view.x += (target.x - view.x) * k
  view.y += (target.y - view.y) * k
}

// ---- Time --------------------------------------------------------------------
let pos = 0, playing = false, prev = performance.now(), lag = 0
// About two and a half minutes for the whole history at 1x, whatever its
// length, but never so quick a change can't be seen to land.
const perStage = () => Math.min(330, Math.max(110, 150000 / S)) / Number(speedSel.value)
const ease = t => t * t * (3 - 2 * t)

// How visible something is between stage s and s+1, t of the way there:
// [alpha, state] where state 1 = arriving, -1 = leaving.
function fade(p, s, t) {
  const a = p[s], b = s < last ? p[s + 1] : a
  if (a && b) return [1, 0]
  if (!a && !b) return [0, 0]
  return a ? [1 - t, -1] : [t, 1]
}

function frame(now) {
  if (playing) {
    pos = Math.min(last, pos + (now - prev) / perStage())
    if (pos >= last) { playing = false; playLabel(); finish(now) }
    slider.value = pos
    slider.style.setProperty('--at', (last ? pos / last * 100 : 0) + '%')
  }
  lag = Math.min(lag + (now - prev), 100)
  prev = now
  if (!introDone) opening(now)
  else {
    // Edits land as their stage starts arriving, with the new code beside them.
    for (let f = Math.floor(pos); lastFloor < f; ) {
      lastFloor++
      for (const i of changes[lastFloor + 1] || []) pulseAt[i] = now
    }
    // Physics on a fixed step, so it behaves the same at any frame rate.
    const s = Math.floor(pos)
    for (let i = 0; i < N; i++) {
      const on = nodeIn[i][s] || (s < last && nodeIn[i][s + 1])
      if (on && !live[i]) spawn(i)
      live[i] = on ? 1 : 0
    }
    while (lag >= 16) { step(s); lag -= 16 }
    // The speck, there until the first files have come out of it.
    placeSeed(clamp(1 - pos / 1.5))
  }
  if (follow) frameCamera()
  draw()
  requestAnimationFrame(frame)
}

// A connection bows slightly to one side, as graphify draws them: straight
// lines through a dense cluster read as a scribble, gentle curves as bundles.
function curve(a, b) {
  const x1 = sx(a), y1 = sy(a), x2 = sx(b), y2 = sy(b)
  ctx.moveTo(x1, y1)
  ctx.quadraticCurveTo((x1 + x2) / 2 - (y2 - y1) * 0.12, (y1 + y2) / 2 + (x2 - x1) * 0.12, x2, y2)
}

function draw() {
  const s = Math.floor(pos), t = ease(pos - s), z = zoom()
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
  ctx.globalCompositeOperation = 'source-over'
  ctx.clearRect(0, 0, W, H)

  // The file and folder tree first, faint, beneath the code.
  const width = 0.6 * z
  ctx.lineWidth = 0.5 * z
  ctx.strokeStyle = P.tree
  ctx.beginPath()
  const batches = new Map(), changing = []
  for (let e = 0; e < edges.length; e++) {
    // Over the opening, today's connections, while both ends are still there.
    const [alpha, state] = introDone ? fade(edgeIn[e], s, t) : edgeIn[e][last] && live[edges[e][0]] && live[edges[e][1]] ? [1, 0] : [0, 0]
    if (!alpha) continue
    if (state) { changing.push([e, alpha, state]); continue }
    if (edges[e][2]) { const [a, b] = edges[e]; ctx.moveTo(sx(a), sy(a)); ctx.lineTo(sx(b), sy(b)); continue }
    const c = colourOf[edges[e][0]]
    const list = batches.get(c)
    list ? list.push(e) : batches.set(c, [e])
  }
  ctx.stroke()

  // The code's own connections, added together ('lighter') so a bundle glows
  // where many run side by side (on paper, multiplied, so it darkens). Batched
  // by colour; changing ones go alone.
  ctx.globalCompositeOperation = P.blend
  ctx.lineWidth = width
  for (const [c, list] of batches) {
    ctx.strokeStyle = `rgba(${rgb(c)},0.3)`
    ctx.beginPath()
    for (const e of list) curve(edges[e][0], edges[e][1])
    ctx.stroke()
  }
  ctx.lineWidth = width * 2
  for (const [e, alpha, state] of changing) {
    const [a, b] = edges[e]
    const k = edges[e][2] ? 0.45 : 1
    ctx.strokeStyle = state > 0 ? `rgba(${P.fresh},${0.85 * alpha * k})` : `rgba(${P.removed},${0.8 * alpha * k})`
    ctx.beginPath(); curve(a, b); ctx.stroke()
  }

  ctx.globalCompositeOperation = 'source-over'
  const arriving = []
  for (let i = 0; i < N; i++) {
    const [alpha, state] = introDone ? fade(nodeIn[i], s, t) : [live[i] ? 1 - gone[i] : 0, 0]
    if (!alpha) continue
    // An edited piece swells a little and settles back -- up and down once,
    // over the pulse -- glowing while it does.
    const age = performance.now() - pulseAt[i], k = age >= 0 && age < PULSE ? 1 - age / PULSE : 0
    const swell = k ? Math.sin(Math.PI * age / PULSE) : 0
    const kind = kindOf[i], x = sx(i), y = sy(i)
    const r = (kind === 2 ? 1.6 + Math.sqrt(nodes[i][3]) * 0.25 : kind === 1 ? 1 : 1 + Math.sqrt(nodes[i][3]) * 0.4) * z * (1 + 0.6 * swell)
    ctx.globalAlpha = alpha * (kind === 1 ? 0.6 : kind === 2 ? 0.55 : 1)
    if (kind === 2) {
      // Folders: small open squares, pale, so they read as the frame the
      // code hangs from rather than as code.
      ctx.strokeStyle = state < 0 ? `rgb(${P.removed})` : P.folder; ctx.lineWidth = 0.9
      ctx.strokeRect(x - r, y - r, r * 2, r * 2)
    } else {
      ctx.fillStyle = state < 0 ? `rgb(${P.removed})` : kind === 1 ? P.other : colourOf[i]
      ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill()
    }
    if (k && state === 0) {
      ctx.globalCompositeOperation = P.blend
      ctx.globalAlpha = 0.45 * swell
      ctx.fillStyle = kind === 2 ? P.folder : colourOf[i]
      ctx.beginPath(); ctx.arc(x, y, r + 4 * swell * z, 0, Math.PI * 2); ctx.fill()
      // A white heart to an edit -- not to the ripple at the end, where
      // thousands together would only be a white blur.
      if (!ended) {
        ctx.globalAlpha = 0.8 * swell
        ctx.fillStyle = P.ring
        ctx.beginPath(); ctx.arc(x, y, r * 0.8, 0, Math.PI * 2); ctx.fill()
      }
      ctx.globalCompositeOperation = 'source-over'
    }
    if (state > 0) {
      arriving.push(i)
      ctx.globalAlpha = 1 - t
      ctx.strokeStyle = P.ring; ctx.lineWidth = 1.4
      ctx.beginPath(); ctx.arc(x, y, r + 1.5 + t * 9, 0, Math.PI * 2); ctx.stroke()
    }
  }
  // Names of what just arrived, as Gource shows its files -- unless a whole
  // batch lands at once, when they would only be a smear.
  if (arriving.length && arriving.length <= 30) {
    ctx.font = '11px ui-monospace, Consolas, monospace'
    ctx.globalAlpha = Math.min(1, 1.6 * (1 - t))
    ctx.fillStyle = P.label
    for (const i of arriving) if (nodes[i][4]) ctx.fillText(nodes[i][4], sx(i) + 6, sy(i) - 6)
  }
  ctx.globalAlpha = 1

  const shown = Math.round(pos), stage = D.stages[shown]
  dateEl.textContent = new Date(stage.t * 1000).toISOString().slice(0, 16).replace('T', '  ')
  statsEl.textContent = tr.stats(...counts[shown])
  noteEl.textContent = stage.note
  showThen(stage.t)
}

// ---- The app then ----------------------------------------------------------------
// Pictures of the app on each day it changed (scripts/code-shots/capture.mjs):
// for the stage shown, the last day at or before it that has the screen
// chosen. Words in each language, the app's own where it has them.
const THEN_WORDS = {
  en: ['The app then', 'Front page', 'Welcome', 'Atrium Browser', 'Inside an atrium', 'Contributors', 'Not built yet'],
  es: ['La app entonces', 'Portada', 'Bienvenida', 'Explorador de atriums', 'Dentro de un atrium', 'Colaboradores', 'Aún no existía'],
  'pt-BR': ['O app na época', 'Página inicial', 'Boas-vindas', 'Navegador de atriums', 'Dentro de um atrium', 'Colaboradores', 'Ainda não existia'],
  'pt-PT': ['A app na altura', 'Página inicial', 'Boas-vindas', 'Navegador de atriums', 'Dentro de um atrium', 'Colaboradores', 'Ainda não existia'],
  fr: ["L'app à cette date", 'Accueil', 'Bienvenue', 'Explorateur d’atriums', 'Dans un atrium', 'Contributeurs', 'Pas encore construit'],
  de: ['Die App damals', 'Startseite', 'Willkommen', 'Atrium-Übersicht', 'In einem Atrium', 'Unterstützer', 'Noch nicht gebaut'],
  it: ["L'app allora", 'Pagina iniziale', 'Benvenuto', 'Esplora atrium', 'Dentro un atrium', 'Sostenitori', 'Non ancora costruita'],
  ru: ['Приложение тогда', 'Главная', 'Приветствие', 'Обзор атриумов', 'Внутри атриума', 'Участники', 'Ещё не было'],
  zh: ['当时的应用', '首页', '欢迎', 'Atrium 浏览器', 'Atrium 内部', '支持者', '尚未建成'],
  ja: ['当時のアプリ', 'トップページ', 'ようこそ', 'Atrium ブラウザー', 'Atrium の中', '支援者', 'まだありません'],
  ko: ['그때의 앱', '첫 페이지', '환영', 'Atrium 브라우저', 'Atrium 안', '후원자', '아직 없음'],
  hi: ['तब का ऐप', 'मुख्य पृष्ठ', 'स्वागत', 'एट्रियम ब्राउज़र', 'एट्रियम के अंदर', 'योगदानकर्ता', 'अभी बना नहीं था'],
}
const SCREENS = ['landing', 'welcome', 'browse', 'atrium', 'contributors']
const THEN_KEY = 'atrium.codeHistory.then'
let shots = [], screen = 'atrium', thenAt = null, thenShown = ''
const thenEl = document.getElementById('then'), thenImgs = [...document.querySelectorAll('#thenPicture img')]
const thenLarge = document.getElementById('thenLarge')
try { const kept = JSON.parse(localStorage.getItem(THEN_KEY) || '{}'); if (SCREENS.includes(kept.screen)) screen = kept.screen; if (kept.folded) thenEl.classList.add('folded') } catch {}
const keepThen = () => { try { localStorage.setItem(THEN_KEY, JSON.stringify({ screen, folded: thenEl.classList.contains('folded') })) } catch {} }
function drawThen() {
  const w = THEN_WORDS[lang] ?? THEN_WORDS.en
  document.getElementById('thenTitle').textContent = w[0]
  document.getElementById('thenScreen').textContent = w[1 + SCREENS.indexOf(screen)]
  document.getElementById('thenNone').textContent = w[6]
  document.getElementById('thenFold').textContent = thenEl.classList.contains('folded') ? '+' : '–'
  if (thenAt != null) { const t = thenAt; thenAt = null; showThen(t) }
}
function showThen(t) {
  if (!shots.length || t === thenAt) return
  thenAt = t
  let day = null
  for (const entry of shots) { if (entry.t > t) break; if (entry.screens[screen]) day = entry }
  document.getElementById('thenDay').textContent = day ? day.day : ''
  const file = day ? 'shots/' + day.screens[screen] : ''
  document.getElementById('thenNone').style.display = file ? 'none' : ''
  if (file === thenShown) return
  thenShown = file
  // The new one over the old, once it has loaded.
  const [front, back] = thenImgs[0].style.opacity === '0' ? [thenImgs[1], thenImgs[0]] : [thenImgs[0], thenImgs[1]]
  if (!file) { front.style.opacity = back.style.opacity = '0'; return }
  back.onload = () => { if (thenShown === file) { back.style.opacity = '1'; front.style.opacity = '0' } }
  back.src = file
  // The next day's, ready before it's needed.
  const next = shots.find(entry => entry.t > t && entry.screens[screen])
  if (next) new Image().src = 'shots/' + next.screens[screen]
}
const stepScreen = by => { screen = SCREENS[(SCREENS.indexOf(screen) + by + SCREENS.length) % SCREENS.length]; keepThen(); drawThen(); thenAt = null; showThen(D.stages[Math.round(pos)].t) }
document.getElementById('thenPrev').onclick = () => stepScreen(-1)
document.getElementById('thenNext').onclick = () => stepScreen(1)
document.getElementById('thenFold').onclick = () => { thenEl.classList.toggle('folded'); keepThen(); drawThen() }
document.getElementById('thenPicture').onclick = () => {
  if (!thenShown) return
  thenLarge.querySelector('img').src = thenShown
  thenLarge.classList.add('open')
}
thenLarge.onclick = () => thenLarge.classList.remove('open')
addEventListener('keydown', e => { if (e.key === 'Escape') thenLarge.classList.remove('open') })
thenImgs[1].style.opacity = '0'
fetch('shots/shots.json', { cache: 'no-cache' }).then(r => (r.ok ? r.json() : [])).then(list => {
  shots = list.filter(entry => entry && Object.keys(entry.screens || {}).length).sort((a, b) => a.t - b.t)
  if (!shots.length) return
  document.body.classList.add('has-then')
  drawThen()
  showThen(D.stages[Math.round(pos)].t)
}).catch(() => {})

// ---- Controls ------------------------------------------------------------------
function playLabel() { playBtn.textContent = playing ? tr.pause : introDone && pos >= last ? tr.replay : tr.play }
function toggle() {
  if (pos >= last) { pos = 0; lastFloor = 0; live.fill(0); follow = true }
  playing = !playing
  playLabel()
  unend()
}
function unend() { ended = false; document.body.classList.remove('ended') }
playBtn.onclick = toggle
document.getElementById('again').onclick = toggle
addEventListener('keydown', e => {
  if (!introDone) return
  if (e.code === 'Space') { e.preventDefault(); toggle() }
})
slider.oninput = () => { pos = Number(slider.value); lastFloor = Math.floor(pos); playing = false; playLabel(); unend(); slider.style.setProperty('--at', (last ? pos / last * 100 : 0) + '%') }

canvas.addEventListener('wheel', e => {
  e.preventDefault()
  follow = false
  const k = Math.exp(-e.deltaY * 0.0015)
  view.x = e.clientX - (e.clientX - view.x) * k
  view.y = e.clientY - (e.clientY - view.y) * k
  view.s *= k
}, { passive: false })
canvas.addEventListener('dblclick', () => { follow = true })
let drag = null
canvas.addEventListener('pointerdown', e => { drag = { x: e.clientX, y: e.clientY }; canvas.classList.add('dragging'); canvas.setPointerCapture(e.pointerId) })
canvas.addEventListener('pointerup', () => { drag = null; canvas.classList.remove('dragging') })
canvas.addEventListener('pointermove', e => {
  if (drag) {
    follow = false
    view.x += e.clientX - drag.x; view.y += e.clientY - drag.y
    drag = { x: e.clientX, y: e.clientY }; tip.style.display = 'none'; return
  }
  let best = -1, bestD = 64
  for (let i = 0; i < N; i++) {
    if (!live[i]) continue
    const dx = sx(i) - e.clientX, dy = sy(i) - e.clientY, d = dx * dx + dy * dy
    if (d < bestD) { bestD = d; best = i }
  }
  if (best < 0) { tip.style.display = 'none'; return }
  tip.replaceChildren(nodes[best][4] || '(unnamed)')
  const small = document.createElement('small'); small.textContent = nodes[best][5] || tr.tip; tip.append(small)
  tip.style.display = 'block'
  tip.style.left = Math.min(e.clientX + 14, W - tip.offsetWidth - 8) + 'px'
  tip.style.top = (e.clientY + 14) + 'px'
})

// Opened from the landing page, this page is loaded ahead into a frame over it,
// unseen (src/lib/codeHistory.ts), and waits there to be shown: only then does
// it start, as if just opened. Its Back is the landing page's to do -- that
// slides home, where following the link would load the app all over again.
const start = () => requestAnimationFrame(t => { prev = t; frame(t) })
if (window.parent !== window) {
  let started = false
  addEventListener('message', e => {
    if (e.source !== parent || e.data !== 'code-history:show' || started) return
    started = true
    const now = storedLang()
    if (now && now !== lang) setLang(now, false)
    start()
  })
  for (const home of document.querySelectorAll('.home')) home.onclick = e => { e.preventDefault(); parent.postMessage('code-history:back', location.origin) }
  parent.postMessage('code-history:ready', location.origin)
} else start()

// The opening. A speck of light falls from above -- the landing page's light
// -- and where it lands, today's graph comes up around it, under the name.
// Then the graph runs back: each dot drawn into the one it grew out of, the
// newest first, the date running back with it, until only the speck is left
// -- the empty folder it all began in -- and from there the history plays.
// Only Skip cuts it short.
const intro = document.getElementById('intro'), introName = document.getElementById('introName')
// When each part starts, and for how long (ms).
const FALL = 1300, BLOOM = [1100, 700], NAME = [1500, 600, 3700, 500], REWIND = [3800, 3600], OPEN_END = 7700
let introDone = false, openedAt = null
const clamp = v => Math.min(1, Math.max(0, v))
const inOut = t => t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2

// Today's dots, oldest first, and what each runs back into: the oldest it
// connects to of those before it -- the speck, where there's none.
const today = [...Array(N).keys()].filter(i => nodeIn[i][last]).sort((a, b) => born[a] - born[b] || a - b)
const rank = new Int32Array(N).fill(-1)
today.forEach((i, r) => { rank[i] = r })
const into = today.map(i => {
  let best = -1
  for (const j of neighbours[i]) if (rank[j] >= 0 && rank[j] < rank[i] && (best < 0 || rank[j] < rank[best])) best = j
  return best
})
// How far each is on its way back (0 home, 1 gone into what it came from);
// each takes this much of the run, so it's seen to go.
const gone = new Float32Array(N)
const SPAN = Math.max(8, today.length * 0.05)

const seedEl = document.getElementById('seed')
let seedShown = 0
function placeSeed(opacity, y = view.y + SEEDY * view.s, trail = 0) {
  if (!opacity && !seedShown) return
  seedShown = opacity
  seedEl.style.opacity = opacity
  seedEl.style.transform = `translate(${view.x + SEEDX * view.s}px, ${y}px)`
  seedEl.style.setProperty('--trail', trail)
}

function opening(now) {
  if (openedAt === null) {
    openedAt = now
    for (const i of today) { live[i] = 1; X[i] = TX[i]; Y[i] = TY[i]; VX[i] = VY[i] = 0 }
    pos = last
    frameCamera(true)
  }
  const t = now - openedAt
  // The speck falling, its thread of light longest while it's quickest; then
  // where it landed, wherever the view takes that.
  const fall = clamp(t / FALL), ground = view.y + SEEDY * view.s
  placeSeed(clamp(t / 250), fall < 1 ? -20 + (ground + 20) * inOut(fall) : ground, Math.sin(Math.PI * fall))
  // Today's graph, faint under the name; whole as it runs back.
  canvas.style.opacity = clamp((t - BLOOM[0]) / BLOOM[1]) * (0.5 + 0.5 * clamp((t - REWIND[0]) / 600))
  introName.style.opacity = Math.min(ease(clamp((t - NAME[0]) / NAME[1])), 1 - ease(clamp((t - NAME[2]) / NAME[3])))
  if (t >= REWIND[0]) {
    document.body.classList.add('rewinding')
    // Where the run back is, in dots: from past the newest to before the oldest.
    const R = (today.length + SPAN) * (1 - inOut(clamp((t - REWIND[0]) / REWIND[1])))
    for (let r = 0; r < today.length; r++) {
      const i = today[r], j = into[r], k = clamp((r + SPAN - R) / SPAN), e = ease(k)
      gone[i] = k
      live[i] = k < 1 ? 1 : 0
      X[i] = TX[i] + ((j >= 0 ? X[j] : SEEDX) - TX[i]) * e
      Y[i] = TY[i] + ((j >= 0 ? Y[j] : SEEDY) - TY[i]) * e
    }
    pos = R > 0 ? born[today[Math.max(0, Math.min(today.length - 1, Math.floor(R - SPAN / 2)))]] : 0
  }
  if (t >= OPEN_END) endIntro()
}

function endIntro() {
  if (introDone) return
  introDone = true
  intro.remove()
  skipBtn.remove()
  canvas.style.opacity = ''
  pos = 0; lastFloor = 0; live.fill(0); follow = true
  document.body.classList.remove('intro', 'rewinding')
  if (!playing) toggle()
  // How to move about, said once as it starts.
  document.body.classList.add('hinting')
  setTimeout(() => document.body.classList.remove('hinting'), 8000)
}
const skipBtn = document.getElementById('skip')
skipBtn.onclick = endIntro

// At today: a ripple of light out from where it began across all of it, the
// view drawn back to take it in, and where to go from here.
function finish(now) {
  ended = true
  document.body.classList.add('ended')
  const far = i => Math.hypot(TX[i] - SEEDX, TY[i] - SEEDY)
  let reach = 1e-6
  for (let i = 0; i < N; i++) if (live[i]) reach = Math.max(reach, far(i))
  for (let i = 0; i < N; i++) if (live[i]) pulseAt[i] = now + 1600 * far(i) / reach
}

// The words, now that everything they go into is here.
setLang(lang, false)
